// build-specimens.mjs — generate the website's static specimens from the two
// pure renderers. Static examples and print specimens must be generated by
// widget-view.js and factor-view.js; hand-drawn HTML lookalikes are not
// authoritative (edition-6 implementation handoff). Output is a set of
// Zola partials under website/zola/templates/partials/generated/; the
// website stays JavaScript-free because generation happens at build time.

import { mkdirSync, writeFileSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

import { renderWidget, STATUS_STATES, STATUS_WIDTHS, STATUS_SCALES } from "./widget-view.js";
import { renderFactor, FACTOR_VIEWS, FACTOR_WIDTHS } from "./factor-view.js";

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, "..", "..");
const outDir = join(repo, "website", "zola", "templates", "partials", "generated");

const statesDoc = JSON.parse(readFileSync(join(here, "widget-states.json"), "utf8"));
const copyDoc = JSON.parse(readFileSync(join(here, "widget-copy-v5.json"), "utf8"));
const en = copyDoc.packs.en;

function factorCard(kind, opts = {}) {
  return renderFactor({
    view: kind,
    copy: opts.copy ?? en,
    email: opts.email ?? "you@example.com",
    code: opts.code ?? "123456",
    ...opts,
  });
}

function specItem(label, markup) {
  return `<div class="spec-item"><div class="spec-stage">${markup}</div><p class="mono-caption">${label}</p></div>`;
}

function wrap(title, inner) {
  return (
    "{# GENERATED by packages/kiwicaptcha-widget-system/build-specimens.mjs. #}\n" +
    `<section class="spec-gallery">\n<h3 class="gallery-title">${title}</h3>\n${inner}\n</section>\n`
  );
}

mkdirSync(outDir, { recursive: true });

// 1. The ten status states at 352 px (section 04/05 specimen order).
const statusOrder = [
  ["pending", "PENDING"], ["connecting", "CONNECTING"], ["solving", "SOLVING"],
  ["done", "DONE"], ["idle", "IDLE"], ["expired", "EXPIRED"],
  ["failed", "FAILED"], ["worker-unavailable", "WORKER-UNAVAILABLE"],
  ["execution-unavailable", "EXECUTION-UNAVAILABLE"], ["solver-mismatch", "SOLVER-MISMATCH"],
];
const statusHtml = statusOrder.map(([state, label]) =>
  specItem(label, renderWidget({
    state, copy: en.states[state], icon: statesDoc.states[state].icon,
  }))
).join("\n");
for (const [state] of statusOrder) {
  writeFileSync(join(outDir, `status-${state}.html`),
    "{# GENERATED status card. #}\n" +
    renderWidget({ state, copy: en.states[state], icon: statesDoc.states[state].icon }) + "\n");
}
writeFileSync(join(outDir, "gallery-status.html"),
  wrap("Ten states. Different recovery contracts.",
    `<div class="spec-grid">\n${statusHtml}\n</div>`));

// 2. The factor sequence at 384 px (sections 06-11 specimen order).
const factorOrder = [
  ["requested", "REQUESTED"], ["address", "ADDRESS"], ["sending", "SENDING / REQUIRED ADAPTER VIEW"],
  ["code", "CODE"], ["verifying", "VERIFYING / REQUIRED ADAPTER VIEW"],
  ["delivery-error", "DELIVERY-ERROR / REQUIRED ADAPTER VIEW"],
  ["code-error", "CODE-ERROR / REQUIRED ADAPTER VIEW"],
  ["expired", "EXPIRED / REQUIRED ADAPTER VIEW"],
  ["rate-limited", "RATE-LIMITED / REQUIRED ADAPTER VIEW"],
  ["service-unavailable", "SERVICE-UNAVAILABLE / REQUIRED ADAPTER VIEW"],
  ["response", "RESPONSE"],
];
const factorHtml = factorOrder.map(([kind, label]) =>
  specItem(label, factorCard(kind))
).join("\n");
writeFileSync(join(outDir, "gallery-factor.html"),
  wrap("One action gets visual priority.",
    `<div class="spec-grid spec-grid--factor">\n${factorHtml}\n</div>`));

// 3. Resilient layout: widths, locales (with RTL), themes, text sizes.
const widths = STATUS_WIDTHS.map((width) =>
  specItem(`${width} PX`, renderWidget({
    state: "solver-mismatch", copy: en.states["solver-mismatch"],
    icon: statesDoc.states["solver-mismatch"].icon, width,
  }))
).join("\n");
const factorWidths = FACTOR_WIDTHS.map((width) =>
  specItem(`${width} PX`, factorCard("code", { width }))
).join("\n");
const locales = Object.entries(copyDoc.packs).map(([lang, pack]) =>
  specItem(`${lang.toUpperCase()}${pack.dir === "rtl" ? " / RTL" : ""}`,
    renderWidget({
      state: "failed", copy: pack.states.failed,
      icon: statesDoc.states.failed.icon,
    }))
).join("\n");
const dark = [
  specItem("STATUS / DARK", renderWidget({
    state: "solving", copy: en.states.solving,
    icon: statesDoc.states.solving.icon, theme: "dark",
  })),
  specItem("RECOVERY / DARK", renderWidget({
    state: "failed", copy: en.states.failed,
    icon: statesDoc.states.failed.icon, theme: "dark",
  })),
  specItem("FACTOR / DARK", factorCard("code", { theme: "dark", code: "" })),
].join("\n");
const scales = [
  specItem("100 PERCENT COMPONENT TEXT", renderWidget({
    state: "solving", copy: en.states.solving, icon: statesDoc.states.solving.icon,
  })),
  specItem("200 PERCENT COMPONENT TEXT", renderWidget({
    state: "solving", copy: en.states.solving, icon: statesDoc.states.solving.icon, scale: 2,
  })),
  specItem("FACTOR / 200 PERCENT", factorCard("address", { scale: 2 })),
].join("\n");
writeFileSync(join(outDir, "gallery-matrix.html"),
  wrap("Typography can grow. The layout follows.",
    `<div class="spec-grid"><h4 class="gallery-sub">Status widths</h4>\n${widths}</div>\n` +
    `<div class="spec-grid spec-grid--factor"><h4 class="gallery-sub">Factor widths</h4>\n${factorWidths}</div>\n` +
    `<div class="spec-grid"><h4 class="gallery-sub">Locale packs (proposed copy; native review is a release task)</h4>\n${locales}</div>\n` +
    `<div class="spec-grid"><h4 class="gallery-sub">Dark theme</h4>\n${dark}</div>\n` +
    `<div class="spec-grid"><h4 class="gallery-sub">Component text sizes</h4>\n${scales}</div>`));

// 4. Single slots for the home hero and the brand board.
writeFileSync(join(outDir, "hero-widget.html"),
  "{# GENERATED home hero status card. #}\n" +
  renderWidget({ state: "done", copy: en.states.done, icon: "check" }) + "\n");
writeFileSync(join(outDir, "brand-widget.html"),
  "{# GENERATED brand board component row. #}\n" +
  renderWidget({ state: "done", copy: en.states.done, icon: "check" }) + "\n");
writeFileSync(join(outDir, "prior-widget.html"),
  "{# GENERATED prior-edition specimen slot (current component). #}\n" +
  renderWidget({ state: "solving", copy: en.states.solving, icon: "none" }) + "\n");

console.log("specimens generated:", outDir);
